from pptx import Presentation

prs = Presentation('/root/Awesome-Agent-Papers.pptx')

for slide_idx, slide in enumerate(prs.slides):
    print(f"\n=== Slide {slide_idx + 1} ===")
    for shape_idx, shape in enumerate(slide.shapes):
        print(f"Shape {shape_idx}: {shape.shape_type}")
        if hasattr(shape, "text"):
            print(f"  Text: {repr(shape.text[:100])}")
        if hasattr(shape, "text_frame"):
            print(f"  Has text_frame: True")
            for para_idx, para in enumerate(shape.text_frame.paragraphs):
                print(f"    Paragraph {para_idx}: {repr(para.text[:80])}")
                for run in para.runs:
                    print(f"      Font: {run.font.name}, Size: {run.font.size}, Bold: {run.font.bold}")
EOF
